#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>

using namespace std;

const int MAX = 2002;
const int INF = 1e9;

int capacity[MAX][MAX];
vector<int> graph[MAX];
bool visited[MAX];
int parent[MAX];

int directions[][2] = { {1,0}, {0,1}, {-1,0}, {0,-1} };

int dfs(int u) {
    if (u == 1) return INF;
    visited[u] = true;
    for (auto v : graph[u]) {
        if (!visited[v] && capacity[u][v] > 0) {
            int flow = dfs(v);
            if (flow > 0) {
                parent[v] = u;
                return min(flow, capacity[u][v]);
            }
        }
    }
    return 0;
}

int computeMaxFlow() {
    int totalFlow = 0;
    while (true) {
        memset(visited, false, sizeof(visited));
        int flow = dfs(0);
        if (flow == 0) break;
        totalFlow += flow;
        int v = 1;
        while (v != 0) {
            int u = parent[v];
            capacity[u][v] -= flow;
            capacity[v][u] += flow;
            v = u;
        }
    }
    return totalFlow;
}

int main() {
    ios::sync_with_stdio(false);
    int size, timeLimit;
    cin >> size >> timeLimit;

    for (int i = 0; i < 2 * size * size + 2; ++i) {
        graph[i].clear();
        for (int j = 0; j < 2 * size * size + 2; ++j)
            capacity[i][j] = 0;
    }

    vector<string> sciLabs(size), capLabs(size);
    int vert[50][50][2];
    int malfunctionIdx;

    int N = 2;
    for (int i = 0; i < size; ++i) {
        cin >> sciLabs[i];
        for (int j = 0; j < size; ++j) {
            if (sciLabs[i][j] >= '1' && sciLabs[i][j] <= '9') {
                capacity[0][N] = sciLabs[i][j] - '0';
                graph[0].push_back(N);
                graph[N].push_back(0);
                vert[i][j][0] = N++;
            } else if (sciLabs[i][j] == 'Z') {
                malfunctionIdx = 100 * i + j;
                sciLabs[i][j] = 'Y';
            }
        }
    }

    int M = N;
    for (int i = 0; i < size; ++i) {
        cin >> capLabs[i];
        for (int j = 0; j < size; ++j) {
            if (capLabs[i][j] >= '1' && capLabs[i][j] <= '9') {
                capacity[M][1] = capLabs[i][j] - '0';
                graph[M].push_back(1);
                vert[i][j][1] = M++;
            }
        }
    }

    int die[50][50];
    for (int i = 0; i < size; ++i)
        for (int j = 0; j < size; ++j)
            die[i][j] = timeLimit + 1;
    die[malfunctionIdx / 100][malfunctionIdx % 100] = 0;

    queue<int> q;
    q.push(malfunctionIdx);
    while (!q.empty()) {
        int x = q.front(); q.pop();
        int y = x % 100; x /= 100;
        for (auto d : directions) {
            int nx = x + d[0], ny = y + d[1];
            if (nx >= 0 && nx < size && ny >= 0 && ny < size && sciLabs[nx][ny] != 'Y' && die[nx][ny] > die[x][y] + 1) {
                die[nx][ny] = die[x][y] + 1;
                q.push(100 * nx + ny);
            }
        }
    }

    int reach[50][50];
    for (int i = 0; i < size; ++i)
        for (int j = 0; j < size; ++j)
            reach[i][j] = timeLimit + 1;

    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            if (sciLabs[i][j] >= '1' && sciLabs[i][j] <= '9') {
                for (int x = 0; x < size; ++x)
                    for (int y = 0; y < size; ++y)
                        reach[x][y] = timeLimit + 1;
                reach[i][j] = 0;
                if (capLabs[i][j] >= '1' && capLabs[i][j] <= '9') {
                    capacity[vert[i][j][0]][vert[i][j][1]] = INF;
                    graph[vert[i][j][0]].push_back(vert[i][j][1]);
                    graph[vert[i][j][1]].push_back(vert[i][j][0]);
                }
                queue<int> q2;
                q2.push(100 * i + j);
                while (!q2.empty()) {
                    int x = q2.front(); q2.pop();
                    int y = x % 100; x /= 100;
                    for (auto d : directions) {
                        int nx = x + d[0], ny = y + d[1];
                        if (nx >= 0 && nx < size && ny >= 0 && ny < size && sciLabs[nx][ny] != 'Y' && reach[nx][ny] > reach[x][y] + 1) {
                            if (capLabs[nx][ny] >= '1' && capLabs[nx][ny] <= '9') {
                                if (reach[x][y] + 1 <= die[nx][ny]) {
                                    capacity[vert[i][j][0]][vert[nx][ny][1]] = INF;
                                    graph[vert[i][j][0]].push_back(vert[nx][ny][1]);
                                    graph[vert[nx][ny][1]].push_back(vert[i][j][0]);
                                }
                            }
                            if (reach[x][y] + 1 < die[nx][ny]) {
                                reach[nx][ny] = reach[x][y] + 1;
                                q2.push(100 * nx + ny);
                            }
                        }
                    }
                }
            }
        }
    }

    cout << computeMaxFlow() << endl;
    return 0;
}
